#!/usr/bin/env python3
"""Descriptive analysis for the Clock Start synthetic-vignette pilot.

This program deliberately makes no causal, representativeness, correctness, or
policy-effectiveness claims. See analysis/README.md and research/protocol.md.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
import math
import random
import sys
from collections import Counter, defaultdict
from datetime import datetime, timezone
from itertools import combinations
from pathlib import Path
from typing import Dict, Iterable, List, Mapping, Sequence

CASE_IDS = tuple(f"S{i:02d}" for i in range(1, 9))
DECISIONS = ("report", "do_not_report", "insufficient_information")
COLUMNS = (
    "reviewer_id",
    "case_id",
    "case_order",
    "report_decision",
    "clock_start",
    "confidence",
)
CLOCK_EVENTS = {
    "S01": {"S01-E1", "S01-E2", "S01-E3", "S01-E4", "no_clock"},
    "S02": {"S02-E1", "S02-E2", "S02-E3", "S02-E4", "no_clock"},
    "S03": {"S03-E1", "S03-E2", "S03-E3", "S03-E4", "no_clock"},
    "S04": {"S04-E1", "S04-E2", "S04-E3", "S04-E4", "no_clock"},
    "S05": {"S05-E1", "S05-E2", "S05-E3", "S05-E4", "S05-E5", "no_clock"},
    "S06": {"S06-E1", "S06-E2", "S06-E3", "S06-E4", "S06-E5", "no_clock"},
    "S07": {"S07-E1", "S07-E2", "S07-E3", "S07-E4", "S07-E5", "no_clock"},
    "S08": {"S08-E1", "S08-E2", "S08-E3", "S08-E4", "S08-E5", "no_clock"},
}


class ValidationError(ValueError):
    """The input cannot be analysed without silent repair."""


def _parse_int(value: str, field: str, line: int, low: int, high: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(f"line {line}: {field} must be an integer") from exc
    if str(parsed) != value.strip() or not low <= parsed <= high:
        raise ValidationError(f"line {line}: {field} must be in [{low}, {high}]")
    return parsed


def load_rows(path: Path) -> tuple[List[dict], str]:
    raw = path.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise ValidationError("input must be UTF-8 CSV") from exc

    reader = csv.DictReader(text.splitlines())
    if reader.fieldnames != list(COLUMNS):
        raise ValidationError(
            f"CSV header must be exactly {','.join(COLUMNS)}; got {reader.fieldnames}"
        )

    rows: List[dict] = []
    seen = set()
    orders = defaultdict(set)
    reviewers = set()
    for line, item in enumerate(reader, start=2):
        if None in item or any(item[c] is None for c in COLUMNS):
            raise ValidationError(f"line {line}: wrong number of fields")
        row = {c: item[c].strip() for c in COLUMNS}
        reviewer = row["reviewer_id"]
        case = row["case_id"]
        if not reviewer or "@" in reviewer or any(x in reviewer for x in (",", "\n", "\r")):
            raise ValidationError(f"line {line}: reviewer_id must be a non-identifying ID")
        if reviewer.startswith("EXAMPLE"):
            raise ValidationError(
                "example/synthetic reviewer IDs are refused; do not report example data as results"
            )
        if case not in CASE_IDS:
            raise ValidationError(f"line {line}: unknown case_id {case!r}")
        if row["report_decision"] not in DECISIONS:
            raise ValidationError(f"line {line}: invalid report_decision")
        if row["clock_start"] not in CLOCK_EVENTS[case]:
            raise ValidationError(f"line {line}: clock_start is not valid for {case}")
        row["case_order"] = _parse_int(row["case_order"], "case_order", line, 1, 8)
        row["confidence"] = _parse_int(row["confidence"], "confidence", line, 0, 100)
        if (reviewer, case) in seen:
            raise ValidationError(f"line {line}: duplicate reviewer–case row")
        if row["case_order"] in orders[reviewer]:
            raise ValidationError(f"line {line}: duplicate case_order for reviewer")
        seen.add((reviewer, case))
        orders[reviewer].add(row["case_order"])
        reviewers.add(reviewer)
        rows.append(row)

    if not rows:
        raise ValidationError("input has no response rows")
    if len(reviewers) < 2:
        raise ValidationError("at least two reviewers are required for agreement analysis")
    return rows, digest


def _counts_and_proportions(values: Iterable[str], categories: Sequence[str]) -> dict:
    values = list(values)
    counts = Counter(values)
    denominator = len(values)
    return {
        "denominator": denominator,
        "counts": {category: counts.get(category, 0) for category in categories},
        "proportions": {
            category: (counts.get(category, 0) / denominator if denominator else None)
            for category in categories
        },
    }


def _quantile(sorted_values: Sequence[float], q: float) -> float:
    if not sorted_values:
        raise ValueError("quantile of empty sequence")
    position = (len(sorted_values) - 1) * q
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return sorted_values[lower]
    weight = position - lower
    return sorted_values[lower] * (1 - weight) + sorted_values[upper] * weight


def _raw_pairwise_agreement(rows: Sequence[dict], reviewers: Sequence[str]) -> dict:
    by_reviewer = {
        reviewer: {row["case_id"]: row["report_decision"] for row in rows if row["reviewer_id"] == reviewer}
        for reviewer in reviewers
    }
    total_shared = 0
    total_agree = 0
    pairs_with_overlap = 0
    pair_agreements = []
    for left, right in combinations(reviewers, 2):
        shared = set(by_reviewer[left]) & set(by_reviewer[right])
        if not shared:
            continue
        pairs_with_overlap += 1
        agree = sum(by_reviewer[left][case] == by_reviewer[right][case] for case in shared)
        total_shared += len(shared)
        total_agree += agree
        pair_agreements.append(agree / len(shared))
    return {
        "definition": "Agreeing reviewer-pair/case comparisons divided by all shared reviewer-pair/case comparisons; all three categories retained.",
        "reviewer_pairs_total": len(reviewers) * (len(reviewers) - 1) // 2,
        "reviewer_pairs_with_overlap": pairs_with_overlap,
        "shared_comparisons": total_shared,
        "agreements": total_agree,
        "micro_agreement": total_agree / total_shared if total_shared else None,
        "mean_pair_agreement": (
            sum(pair_agreements) / len(pair_agreements) if pair_agreements else None
        ),
    }


def _fleiss_kappa(rows: Sequence[dict], reviewers: Sequence[str], warnings: List[str]) -> dict:
    by_case = defaultdict(list)
    for row in rows:
        by_case[row["case_id"]].append(row)
    complete_cases = [case for case in CASE_IDS if len(by_case[case]) == len(reviewers)]
    omitted = [case for case in CASE_IDS if 0 < len(by_case[case]) < len(reviewers)]
    if omitted:
        warnings.append(
            "Fleiss' kappa uses only cases answered by every reviewer; incomplete cases omitted: "
            + ", ".join(omitted)
        )
    n = len(reviewers)
    if n < 2 or len(complete_cases) < 2:
        warnings.append("Fleiss' kappa requires at least two reviewers and two complete cases.")
        return {"value": None, "complete_cases_used": complete_cases}

    matrices = []
    for case in complete_cases:
        counts = Counter(row["report_decision"] for row in by_case[case])
        matrices.append([counts.get(category, 0) for category in DECISIONS])
    subject_scores = [
        (sum(value * value for value in matrix) - n) / (n * (n - 1))
        for matrix in matrices
    ]
    p_bar = sum(subject_scores) / len(subject_scores)
    category_totals = [sum(matrix[j] for matrix in matrices) for j in range(len(DECISIONS))]
    total = n * len(matrices)
    marginal_probs = [value / total for value in category_totals]
    p_e = sum(value * value for value in marginal_probs)
    value = (p_bar - p_e) / (1 - p_e) if not math.isclose(1 - p_e, 0.0, abs_tol=1e-15) else None
    if value is None:
        warnings.append("Fleiss' kappa is undefined because chance agreement is 1 (only one category used).")
    return {
        "value": value,
        "observed_mean_agreement": p_bar,
        "chance_agreement_from_marginals": p_e,
        "reviewers_per_complete_case": n,
        "complete_cases_used": complete_cases,
        "incomplete_cases_omitted": omitted,
        "interpretation_warning": "Agreement is not correctness; kappa depends on category prevalence and marginals.",
    }


def _bootstrap_report_proportions(
    rows: Sequence[dict], reviewers: Sequence[str], samples: int, seed: int
) -> dict:
    rng = random.Random(seed)
    by_reviewer = {
        reviewer: [row for row in rows if row["reviewer_id"] == reviewer]
        for reviewer in reviewers
    }
    draws = defaultdict(list)
    successful = 0
    for _ in range(samples):
        sampled_reviewers = [rng.choice(reviewers) for _ in reviewers]
        sampled_rows = [row for reviewer in sampled_reviewers for row in by_reviewer[reviewer]]
        if not sampled_rows:
            continue
        successful += 1
        for case in CASE_IDS:
            decisions = [row["report_decision"] for row in sampled_rows if row["case_id"] == case]
            if decisions:
                draws[case].append(
                    sum(decision == "report" for decision in decisions) / len(decisions)
                )
    result = {}
    for case in CASE_IDS:
        values = sorted(draws[case])
        result[case] = {
            "successful_resamples_with_case": len(values),
            "ci_95_percentile": (
                [_quantile(values, 0.025), _quantile(values, 0.975)] if values else None
            ),
        }
    return {
        "method": "Resample reviewer IDs with replacement, retaining all of each sampled reviewer's cases and repeated selections.",
        "seed": seed,
        "requested_resamples": samples,
        "successful_resamples": successful,
        "target": "Observed fraction of non-missing case responses labelled report; not a population-representative estimate.",
        "by_case": result,
    }


def analyze(rows: Sequence[dict], digest: str, bootstrap_samples: int, seed: int) -> dict:
    reviewers = sorted({row["reviewer_id"] for row in rows})
    warnings = [
        "No causal, population-representative, correctness, or policy-effectiveness inference is supported by this descriptive output.",
        "Verify that the input is de-identified, consented response data and not a synthetic/example dataset.",
    ]
    expected = len(reviewers) * len(CASE_IDS)
    if len(rows) != expected:
        warnings.append(
            f"Incomplete response matrix: {len(rows)} rows versus {expected} for all reviewers and cases; inspect denominators."
        )
    if len(reviewers) < 10:
        warnings.append("Very small reviewer sample: bootstrap intervals and agreement estimates are unstable.")

    by_case = {}
    for case in CASE_IDS:
        case_rows = [row for row in rows if row["case_id"] == case]
        decisions = _counts_and_proportions(
            (row["report_decision"] for row in case_rows), DECISIONS
        )
        event_ids = sorted(CLOCK_EVENTS[case], key=lambda value: (value == "no_clock", value))
        clocks = _counts_and_proportions((row["clock_start"] for row in case_rows), event_ids)
        confidence = sorted(row["confidence"] for row in case_rows)
        by_case[case] = {
            "responses": len(case_rows),
            "missing_reviewer_responses": len(reviewers) - len(case_rows),
            "report_decision": decisions,
            "clock_start": clocks,
            "confidence": {
                "mean": sum(confidence) / len(confidence) if confidence else None,
                "median": _quantile(confidence, 0.5) if confidence else None,
                "min": min(confidence) if confidence else None,
                "max": max(confidence) if confidence else None,
            },
        }

    return {
        "metadata": {
            "analysis_version": "0.1.0",
            "generated_utc": datetime.now(timezone.utc).isoformat(),
            "input_sha256": digest,
            "data_status": "UNVERIFIED: inspect consent and provenance before reporting",
            "casebook_version": "0.1",
            "source_alignment_required": True,
        },
        "sample": {
            "reviewers": len(reviewers),
            "cases_present": len({row["case_id"] for row in rows}),
            "response_rows": len(rows),
            "expected_rows_if_complete": expected,
        },
        "by_case": by_case,
        "raw_pairwise_agreement": _raw_pairwise_agreement(rows, reviewers),
        "fleiss_kappa": _fleiss_kappa(rows, reviewers, warnings),
        "cluster_bootstrap": _bootstrap_report_proportions(
            rows, reviewers, bootstrap_samples, seed
        ),
        "warnings": warnings,
    }


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", type=Path, help="de-identified six-column response CSV")
    parser.add_argument("--output", type=Path, help="write JSON here instead of stdout")
    parser.add_argument("--bootstrap-samples", type=int, default=2000)
    parser.add_argument("--seed", type=int, default=20261116)
    args = parser.parse_args(argv)
    if args.bootstrap_samples < 100:
        parser.error("--bootstrap-samples must be at least 100")
    try:
        rows, digest = load_rows(args.input)
        result = analyze(rows, digest, args.bootstrap_samples, args.seed)
    except (OSError, ValidationError) as exc:
        parser.exit(2, f"error: {exc}\n")
    rendered = json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + "\n"
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(rendered, encoding="utf-8")
    else:
        sys.stdout.write(rendered)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

